function show(n,e){document.querySelectorAll(".section").forEach(t=>t.classList.remove("visible")),document.querySelectorAll(".nav-btn").forEach(t=>t.classList.remove("active")),document.getElementById(n).classList.add("visible"),e.classList.add("active"),closeMobileNav(),window.scrollTo({top:0,behavior:"instant"})}function toggleMobileNav(){const n=document.querySelector("nav"),e=document.getElementById("nav-scroll"),t=document.getElementById("nav-hamburger");n.classList.toggle("open"),e.classList.toggle("open"),t.classList.toggle("open"),adjustLayout()}function closeMobileNav(){const n=document.querySelector("nav"),e=document.getElementById("nav-scroll"),t=document.getElementById("nav-hamburger");n.classList.remove("open"),e.classList.remove("open"),t.classList.remove("open"),adjustLayout()}document.addEventListener("click",function(n){document.querySelector("nav").contains(n.target)||closeMobileNav()});function adjustLayout(){const n=document.querySelector("header"),e=document.querySelector("nav"),t=document.querySelector("main");if(!n||!e||!t)return;const o=n.offsetHeight,s=e.offsetHeight;window.innerWidth<=1024?(e.style.top=`${o}px`,t.style.paddingTop=`${o+s+16}px`):(e.style.top="",t.style.paddingTop="")}window.addEventListener("resize",adjustLayout),document.addEventListener("DOMContentLoaded",adjustLayout);
